      '<!DOCTYPE html>\n<html lang="ja">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>QRコード生成ツール</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n            min-height: 100vh;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            padding: 20px;\n        }\n\n        .container {\n            background: white;\n            border-radius: 20px;\n            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\n            padding: 40px;\n            max-width: 500px;\n            width: 100%;\n        }\n\n        h1 {\n            color: #333;\n            text-align: center;\n            margin-bottom: 30px;\n            font-size: 28px;\n        }\n\n        .input-group {\n            margin-bottom: 20px;\n        }\n\n        label {\n            display: block;\n            color: #555;\n            margin-bottom: 8px;\n            font-weight: 500;\n        }\n\n        input[type="text"] {\n            width: 100%;\n            padding: 12px 15px;\n            border: 2px solid #e0e0e0;\n            border-radius: 10px;\n            font-size: 16px;\n            transition: border-color 0.3s;\n        }\n\n        input[type="text"]:focus {\n            outline: none;\n            border-color: #667eea;\n        }\n\n        .size-group {\n            display: flex;\n            gap: 10px;\n            margin-bottom: 20px;\n        }\n\n        .size-group input {\n            flex: 1;\n        }\n\n        button {\n            width: 100%;\n            padding: 14px;\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n            color: white;\n            border: none;\n            border-radius: 10px;\n            font-size: 16px;\n            font-weight: 600;\n            cursor: pointer;\n            transition: transform 0.2s, box-shadow 0.2s;\n        }\n\n        button:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 5px 20px rgba(102, 126, 234, 0.4);\n        }\n\n        button:active {\n            transform: translateY(0);\n        }\n\n        #qrcode {\n            margin-top: 30px;\n            text-align: center;\n            min-height: 256px;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            background: #f8f9fa;\n            border-radius: 10px;\n            padding: 20px;\n        }\n\n        #qrcode canvas, #qrcode img {\n            max-width: 100%;\n            height: auto;\n        }\n\n        .download-btn {\n            margin-top: 15px;\n            background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%);\n            display: none;\n        }\n\n        .download-btn:hover {\n            box-shadow: 0 5px 20px rgba(17, 153, 142, 0.4);\n        }\n\n        .placeholder {\n            color: #999;\n            font-size: 14px;\n        }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <h1>📱 QRコード生成ツール</h1>\n        \n        <div class="input-group">\n            <label for="url">URL を入力してください</label>\n            <input type="text" id="url" placeholder="https://example.com" value="https://www.anthropic.com">\n        </div>\n\n        <div class="input-group">\n            <label for="size">QRコードのサイズ (px)</label>\n            <input type="text" id="size" value="256">\n        </div>\n\n        <button onclick="generateQR()">QRコードを生成</button>\n        \n        <div id="qrcode">\n            <span class="placeholder">ここにQRコードが表示されます</span>\n        </div>\n\n        <button class="download-btn" id="downloadBtn" onclick="downloadQR()">QRコードをダウンロード</button>\n    </div>\n\n    <script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script>\n    <script>\n        let qrcode = null;\n\n        function generateQR() {\n            const url = document.getElementById(\'url\').value.trim();\n            const size = parseInt(document.getElementById(\'size\').value) || 256;\n            const qrcodeDiv = document.getElementById(\'qrcode\');\n            const downloadBtn = document.getElementById(\'downloadBtn\');\n\n            if (!url) {\n                alert(\'URLを入力してください\');\n                return;\n            }\n\n            // 既存のQRコードをクリア\n            qrcodeDiv.innerHTML = \'\';\n            \n            // 新しいQRコードを生成\n            qrcode = new QRCode(qrcodeDiv, {\n                text: url,\n                width: size,\n                height: size,\n                colorDark: "#000000",\n                colorLight: "#ffffff",\n                correctLevel: QRCode.CorrectLevel.H\n            });\n\n            // ダウンロードボタンを表示\n            downloadBtn.style.display = \'block\';\n        }\n\n        function downloadQR() {\n            const canvas = document.querySelector(\'#qrcode canvas\');\n            if (!canvas) {\n                alert(\'先にQRコードを生成してください\');\n                return;\n            }\n\n            // Canvasを画像に変換してダウンロード\n            const url = canvas.toDataURL(\'image/png\');\n            const link = document.createElement(\'a\');\n            link.download = \'qrcode.png\';\n            link.href = url;\n            link.click();\n        }\n\n        // Enterキーで生成\n        document.getElementById(\'url\').addEventListener(\'keypress\', function(e) {\n            if (e.key === \'Enter\') {\n                generateQR();\n            }\n        });\n\n        // ページ読み込み時にデフォルトのQRコードを生成\n        window.addEventListener(\'load\', function() {\n            generateQR();\n        });\n    </script>\n</body>\n</html>',
