      '<!DOCTYPE html>\n<html lang="ja">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>脆弱なチャットアプリ（教育用）</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n        body {\n            font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n            min-height: 100vh;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            padding: 20px;\n        }\n        .container {\n            background: white;\n            border-radius: 15px;\n            box-shadow: 0 20px 60px rgba(0,0,0,0.3);\n            width: 100%;\n            max-width: 600px;\n            height: 80vh;\n            display: flex;\n            flex-direction: column;\n        }\n        .header {\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n            color: white;\n            padding: 20px;\n            border-radius: 15px 15px 0 0;\n        }\n        .header h1 {\n            font-size: 24px;\n            margin-bottom: 5px;\n        }\n        .warning {\n            background: #ff6b6b;\n            color: white;\n            padding: 10px;\n            font-size: 12px;\n            text-align: center;\n        }\n        .chat-area {\n            flex: 1;\n            overflow-y: auto;\n            padding: 20px;\n            background: #f8f9fa;\n        }\n        .message {\n            margin-bottom: 15px;\n            padding: 10px 15px;\n            border-radius: 10px;\n            background: white;\n            box-shadow: 0 2px 5px rgba(0,0,0,0.1);\n        }\n        .message-user {\n            color: #667eea;\n            font-weight: bold;\n            margin-bottom: 5px;\n            font-size: 14px;\n        }\n        .message-content {\n            color: #333;\n            word-wrap: break-word;\n        }\n        .input-area {\n            padding: 20px;\n            background: white;\n            border-radius: 0 0 15px 15px;\n            border-top: 1px solid #e0e0e0;\n        }\n        .input-group {\n            display: flex;\n            gap: 10px;\n        }\n        input[type="text"] {\n            flex: 1;\n            padding: 12px;\n            border: 2px solid #e0e0e0;\n            border-radius: 25px;\n            font-size: 14px;\n            outline: none;\n            transition: border-color 0.3s;\n        }\n        input[type="text"]:focus {\n            border-color: #667eea;\n        }\n        button {\n            padding: 12px 30px;\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n            color: white;\n            border: none;\n            border-radius: 25px;\n            cursor: pointer;\n            font-weight: bold;\n            transition: transform 0.2s;\n        }\n        button:hover {\n            transform: scale(1.05);\n        }\n        button:active {\n            transform: scale(0.95);\n        }\n        .examples {\n            margin-top: 10px;\n            padding: 10px;\n            background: #fff3cd;\n            border-radius: 5px;\n            font-size: 12px;\n        }\n        .examples h3 {\n            color: #856404;\n            margin-bottom: 5px;\n        }\n        .examples code {\n            display: block;\n            background: white;\n            padding: 5px;\n            margin: 3px 0;\n            border-radius: 3px;\n            color: #d63384;\n        }\n    </style>\n</head>\n<body>\n    <div class="container">\n        <div class="header">\n            <h1>🔓 脆弱なチャットアプリ</h1>\n            <small>教育目的のXSSデモ</small>\n        </div>\n        <div class="warning">\n            ⚠️ このアプリは意図的にXSS脆弱性を含んでいます。学習目的のみで使用してください。\n        </div>\n        <div class="chat-area" id="chatArea"></div>\n        <div class="input-area">\n            <div class="input-group">\n                <input type="text" id="userInput" placeholder="ユーザー名を入力..." />\n                <input type="text" id="messageInput" placeholder="メッセージを入力..." />\n                <button onclick="sendMessage()">送信</button>\n            </div>\n            <div class="examples">\n                <h3>試してみるXSSの例：</h3>\n                <code>&lt;script&gt;alert(\'XSS!\')&lt;/script&gt;</code>\n                <code>&lt;img src=x onerror="alert(\'XSS\')"&gt;</code>\n                <code>&lt;h1&gt;HTMLインジェクション&lt;/h1&gt;</code>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        // 脆弱な実装：innerHTML を使用してユーザー入力を直接表示\n        function sendMessage() {\n            const user = document.getElementById(\'userInput\').value;\n            const message = document.getElementById(\'messageInput\').value;\n            \n            if (!user || !message) {\n                alert(\'ユーザー名とメッセージを入力してください\');\n                return;\n            }\n            \n            const chatArea = document.getElementById(\'chatArea\');\n            \n            // ⚠️ 脆弱性: サニタイゼーションなしで innerHTML を使用\n            const messageHTML = `\n                <div class="message">\n                    <div class="message-user">${user}</div>\n                    <div class="message-content">${message}</div>\n                </div>\n            `;\n            \n            chatArea.innerHTML += messageHTML;\n            chatArea.scrollTop = chatArea.scrollHeight;\n            \n            document.getElementById(\'messageInput\').value = \'\';\n        }\n        \n        // Enterキーで送信\n        document.getElementById(\'messageInput\').addEventListener(\'keypress\', function(e) {\n            if (e.key === \'Enter\') {\n                sendMessage();\n            }\n        });\n    </script>\n</body>\n</html>',
