      '<!DOCTYPE html>\n<html lang="ja">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>ようこそ混沌へ</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n        \n        body {\n            font-family: \'Comic Sans MS\', cursive;\n            background: linear-gradient(45deg, #ff0000, #00ff00, #0000ff, #ffff00);\n            background-size: 400% 400%;\n            animation: gradientShift 3s ease infinite;\n            overflow-x: hidden;\n        }\n        \n        @keyframes gradientShift {\n            0% { background-position: 0% 50%; }\n            50% { background-position: 100% 50%; }\n            100% { background-position: 0% 50%; }\n        }\n        \n        h1 {\n            position: absolute;\n            top: 20%;\n            left: 50%;\n            transform: translate(-50%, -50%) rotate(-15deg);\n            font-size: 5em;\n            color: #ff00ff;\n            text-shadow: 5px 5px #00ffff, -5px -5px #ffff00;\n            animation: wobble 0.5s ease-in-out infinite;\n            z-index: 100;\n        }\n        \n        @keyframes wobble {\n            0%, 100% { transform: translate(-50%, -50%) rotate(-15deg) scale(1); }\n            50% { transform: translate(-50%, -50%) rotate(15deg) scale(1.1); }\n        }\n        \n        .container {\n            position: relative;\n            margin: 150px 50px;\n        }\n        \n        p {\n            display: inline-block;\n            margin: 20px;\n            padding: 15px;\n            background: rgba(255, 255, 255, 0.8);\n            border: 5px dashed #ff0000;\n            transform: rotate(5deg);\n            font-size: 1.2em;\n            animation: float 3s ease-in-out infinite;\n        }\n        \n        @keyframes float {\n            0%, 100% { transform: rotate(5deg) translateY(0px); }\n            50% { transform: rotate(-5deg) translateY(-20px); }\n        }\n        \n        .box {\n            position: absolute;\n            width: 100px;\n            height: 100px;\n            background: linear-gradient(45deg, #ff00ff, #00ffff);\n            border-radius: 50% 0 50% 0;\n            animation: spin 2s linear infinite, move 5s ease-in-out infinite;\n        }\n        \n        .box:nth-child(1) { top: 100px; left: 10%; }\n        .box:nth-child(2) { top: 300px; right: 10%; animation-delay: 1s; }\n        .box:nth-child(3) { top: 500px; left: 30%; animation-delay: 2s; }\n        \n        @keyframes spin {\n            from { transform: rotate(0deg); }\n            to { transform: rotate(360deg); }\n        }\n        \n        @keyframes move {\n            0%, 100% { transform: translateX(0) translateY(0); }\n            25% { transform: translateX(50px) translateY(-50px); }\n            50% { transform: translateX(-50px) translateY(50px); }\n            75% { transform: translateX(50px) translateY(50px); }\n        }\n        \n        button {\n            position: fixed;\n            bottom: 20px;\n            left: 50%;\n            transform: translateX(-50%);\n            padding: 20px 40px;\n            font-size: 2em;\n            background: #ff0000;\n            color: #ffff00;\n            border: 10px double #00ff00;\n            cursor: pointer;\n            animation: pulse 0.5s ease infinite;\n            font-family: \'Comic Sans MS\', cursive;\n            font-weight: bold;\n        }\n        \n        @keyframes pulse {\n            0%, 100% { transform: translateX(-50%) scale(1); }\n            50% { transform: translateX(-50%) scale(1.2); }\n        }\n        \n        button:hover {\n            animation: crazy 0.1s ease infinite;\n            background: #00ff00;\n            color: #ff00ff;\n        }\n        \n        @keyframes crazy {\n            0% { transform: translateX(-50%) rotate(0deg); }\n            25% { transform: translateX(-45%) rotate(5deg); }\n            50% { transform: translateX(-55%) rotate(-5deg); }\n            75% { transform: translateX(-45%) rotate(3deg); }\n            100% { transform: translateX(-50%) rotate(0deg); }\n        }\n        \n        .sidebar {\n            position: fixed;\n            top: 0;\n            right: 0;\n            width: 200px;\n            height: 100%;\n            background: repeating-linear-gradient(\n                45deg,\n                #ffff00,\n                #ffff00 10px,\n                #ff00ff 10px,\n                #ff00ff 20px\n            );\n            transform: skewY(-5deg);\n            z-index: 50;\n        }\n        \n        .text {\n            position: absolute;\n            top: 40%;\n            left: 20%;\n            font-size: 3em;\n            color: white;\n            text-shadow: 3px 3px 0 #000;\n            animation: glitch 1s ease infinite;\n        }\n        \n        @keyframes glitch {\n            0% { transform: translate(0); }\n            20% { transform: translate(-5px, 5px); }\n            40% { transform: translate(-5px, -5px); }\n            60% { transform: translate(5px, 5px); }\n            80% { transform: translate(5px, -5px); }\n            100% { transform: translate(0); }\n        }\n    </style>\n</head>\n<body>\n    <h1>🌈 混沌のサイト 🌈</h1>\n    \n    <div class="sidebar"></div>\n    \n    <div class="container">\n        <p>このサイトは完全に意図的です</p>\n        <p style="transform: rotate(-10deg); margin-left: 200px;">CSSを理解しているからこそ作れます</p>\n        <p style="transform: rotate(15deg); margin-left: 100px;">読みにくい?それが狙いです!</p>\n        \n        <div class="box"></div>\n        <div class="box"></div>\n        <div class="box"></div>\n    </div>\n    \n    <div class="text">グルグル</div>\n    \n    <button onclick="alert(\'押しても何も起きません😈\')">押すな危険</button>\n</body>\n</html>',
